public static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {

    // Check if the index is within the bounds of the ByteBuffer
    if (i < 0 || i >= bb.limit()) {
        throw new IndexOutOfBoundsException("Index out of range: " + i);
    }

    // Get the first byte at the current index
    byte b = bb.get(i);

    // Check if the byte is a single-byte character
    if ((b & 0x80) == 0) {
        // If it is, append the character to the StringBuilder
        sb.append((char) b);
        return i + 1;
    }

    // Check if the byte is a multi-byte character
    if ((b & 0xE0) == 0xC0) {
        // If it is, get the next byte and combine it with the current byte
        byte b2 = bb.get(i + 1);
        if ((b2 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
        sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
        return i + 2;
    }

    // Check if the byte is a three-byte character
    if ((b & 0xF0) == 0xE0) {
        // If it is, get the next two bytes and combine them with the current byte
        byte b2 = bb.get(i + 1);
        byte b3 = bb.get(i + 2);
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
        sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
        return i + 3;
    }

    // Check if the byte is a four-byte character
    if ((b & 0xF8) == 0xF0) {
        // If it is, get the next three bytes and combine them with the current byte
        byte b2 = bb.get(i + 1);
        byte b3 = bb.get(i + 2);
        byte b4 = bb.get(i + 3);
        if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) {
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
        sb.append((char) (((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)));
        return i + 4;
    }

    // If the byte is not a valid UTF-8 character, throw an exception
    throw new IllegalArgumentException("Invalid UTF-8 sequence");
}

public int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    // Check if the current frame is null
    if (currentFrame == null) {
        throw new IllegalStateException("Current frame is null");
    }

    // Check if the offset is valid
    if (offset < 0 || offset >= codeLength) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }

    // Check if the number of local variables is valid
    if (numLocal < 0 || numLocal > maxLocals) {
        throw new IllegalArgumentException("Invalid number of local variables: " + numLocal);
    }

    // Check if the number of stack elements is valid
    if (numStack < 0 || numStack > maxStack) {
        throw new IllegalArgumentException("Invalid number of stack elements: " + numStack);
    }

    // Set the current frame's offset, number of local variables, and number of stack elements
    currentFrame.setOffset(offset);
    currentFrame.setNumLocal(numLocal);
    currentFrame.setNumStack(numStack);

    // Return the index of the next element to be written in this frame
    return currentFrame.getNextElementIndex();
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    int newCapacity = Math.max(this.capacity + size, this.capacity * 2);
    byte[] newData = new byte[newCapacity];
    System.arraycopy(this.data, 0, newData, 0, this.capacity);
    this.data = newData;
    this.capacity = newCapacity;
}

