public String format(LoggingEvent event) {
    // Check if the event is null
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Get the conversion pattern from the event
    String conversionPattern = event.getConversionPattern();

    // Check if the conversion pattern is null or empty
    if (conversionPattern == null || conversionPattern.isEmpty()) {
        throw new IllegalArgumentException("Conversion pattern cannot be null or empty");
    }

    // Create a new string builder to build the formatted string
    StringBuilder builder = new StringBuilder();

    // Iterate over the conversion pattern and replace placeholders with event data
    for (int i = 0; i < conversionPattern.length(); i++) {
        char c = conversionPattern.charAt(i);
        if (c == '%') {
            // Check if the next character is a placeholder
            if (i + 1 < conversionPattern.length()) {
                char nextChar = conversionPattern.charAt(i + 1);
                if (nextChar == 'd' || nextChar == 'i' || nextChar == 'o' || nextChar == 'u' || nextChar == 'x' || nextChar == 'X') {
                    // Replace the placeholder with the event data
                    builder.append(event.getData());
                    i++;
                } else if (nextChar == 's') {
                    // Replace the placeholder with the event message
                    builder.append(event.getMessage());
                    i++;
                } else if (nextChar == 'c') {
                    // Replace the placeholder with the event level
                    builder.append(event.getLevel());
                    i++;
                } else if (nextChar == 'C') {
                    // Replace the placeholder with the event logger name
                    builder.append(event.getLoggerName());
                    i++;
                } else if (nextChar == 'M') {
                    // Replace the placeholder with the event method name
                    builder.append(event.getMethodName());
                    i++;
                } else if (nextChar == 'L') {
                    // Replace the placeholder with the event line number
                    builder.append(event.getLineNumber());
                    i++;
                } else if (nextChar == 'F') {
                    // Replace the placeholder with the event file name
                    builder.append(event.getFileName());
                    i++;
                } else if (nextChar == 'P') {
                    // Replace the placeholder with the event thread name
                    builder.append(event.getThreadName());
                    i++;
                } else if (nextChar == 'T') {
                    // Replace the placeholder with the event thread ID
                    builder.append(event.getThreadID());
                    i++;
                } else if (nextChar == 'S') {
                    // Replace the placeholder with the event stack trace
                    builder.append(event.getStackTrace());
                    i++;
                } else {
                    // Unknown placeholder, append the character as is
                    builder.append(c);
                }
            } else {
                // No next character, append the character as is
                builder.append(c);
            }
        } else {
            // Not a placeholder, append the character as is
            builder.append(c);
        }
    }

    // Return the formatted string
    return builder.toString();
}

