public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {

// Check if the byte array is null
if (byteArrayValue == null) {
// If the byte array is null, put the specified number of null bytes into this byte vector
for (int i = 0; i < byteLength; i++) {
this.data[this.length++] = 0;
}
return this;
}

// Check if the byte offset and byte length are valid
if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
throw new IndexOutOfBoundsException("Invalid byte offset or byte length");
}

// Enlarge the byte vector if necessary
if (this.length + byteLength > this.data.length) {
this.enlarge(byteLength);
}

// Copy the bytes from the byte array into this byte vector
System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
this.length += byteLength;

return this;
}

