    if (descriptor.startsWith("(")) {
        // If it's a method descriptor, pop its argument types
        String[] argumentTypes = descriptor.substring(1, descriptor.length() - 1).split(";");
        for (int i = argumentTypes.length - 1; i >= 0; i--) {
            pop(argumentTypes[i]);
        }
    } else {
