public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {

// Check if the output stream is null
if (out == null) {
throw new IllegalArgumentException("Output stream cannot be null");
}

// Check if the LinkedBuffer is null
if (node == null) {
throw new IllegalArgumentException("LinkedBuffer cannot be null");
}

// Initialize the total content size to 0
int totalContentSize = 0;

// Loop through the LinkedBuffer and write each node to the output stream
while (node != null) {

// Write the node to the output stream
out.write(node.getData());

// Increment the total content size by the size of the node
totalContentSize += node.getData().length;

// Move to the next node
node = node.getNext();
}

// Return the total content size
return totalContentSize;
}

