public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Check if the constant pool entry is a CONSTANT_Utf8
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPoolTable.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    ConstantPoolEntry entry = constantPoolTable[constantPoolEntryIndex];
    if (entry.getTag() != ConstantPoolEntry.CONSTANT_Utf8) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 entry, but found " + entry.getTag());
    }

    // Read the string from the constant pool entry
    int stringLength = entry.getUtf8Length();
    if (stringLength > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer is not large enough to hold the string");
    }
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) entry.getUtf8(i);
    }
    return new String(charBuffer, 0, stringLength);
}

