public static String deleteAny(String inString, String charsToDelete) {
  // Check if the input string is null or empty
  if (inString == null || inString.isEmpty()) {
    return inString;
  }

  // Check if the characters to delete string is null or empty
  if (charsToDelete == null || charsToDelete.isEmpty()) {
    return inString;
  }

  // Create a new string builder with the same length as the input string
  StringBuilder result = new StringBuilder(inString.length());

  // Iterate through the input string and append each character to the result string
  // if it is not in the set of characters to delete
  for (int i = 0; i < inString.length(); i++) {
    char c = inString.charAt(i);
    if (!charsToDelete.contains(c)) {
      result.append(c);
    }
  }

  // Return the resulting string
  return result.toString();
}

public final MatchResult match(CharSequence uri) {
  // Check if the URI is null or empty
  if (uri == null || uri.length() == 0) {
    return null;
  }

  // Check if the URI matches the pattern
  if (uri.toString().matches(pattern)) {
    // Extract the matched groups
    Matcher matcher = pattern.matcher(uri);
    if (matcher.find()) {
      // Create a new MatchResult object
      MatchResult result = new MatchResult();
      result.setUri(uri);
      result.setMatchedGroups(matcher.groupCount());
      result.setMatchedGroupValues(matcher.group());
      return result;
    }
  }

  // No match found, return null
  return null;
}

