public int compare(Object aObj1, Object aObj2) {
    // Check if both objects are null
    if (aObj1 == null && aObj2 == null) {
        return 0;
    }

    // Check if one of the objects is null
    if (aObj1 == null || aObj2 == null) {
        return aObj1 == null ? -1 : 1;
    }

    // Check if both objects are the same
    if (aObj1.equals(aObj2)) {
        return 0;
    }

    // Check if both objects are comparable
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        return ((Comparable) aObj1).compareTo(aObj2);
    }

    // If none of the above conditions are met, return 0
    return 0;
}

