public int appendLoopOnAppenders(LoggingEvent event) {

    // Check if the event is valid
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Loop through all attached appenders
    for (Appender appender : getAllAppenders()) {
        try {
            // Call the doAppend method on the appender
            appender.doAppend(event);
        } catch (Exception e) {
            // Log the error and continue to the next appender
            log.error("Error appending event to appender " + appender.getName(), e);
        }
    }

    // Return the number of appenders that were called
    return getAllAppenders().size();
}

