protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Check if the tour is empty
    if (tour.isEmpty()) {
        throw new IllegalArgumentException("Tour must not be empty");
    }

    // Create a new graph path
    GraphPath<V,E> path = new GraphPath<V,E>();

    // Add the first edge to the path
    E firstEdge = tour.iterator().next();
    path.addEdge(firstEdge);

    // Iterate over the remaining edges in the tour
    for (E edge : tour) {
        // Check if the edge is already in the path
        if (path.containsEdge(edge)) {
            // If the edge is already in the path, remove it and add the next edge
            path.removeEdge(edge);
            path.addEdge(edge);
        } else {
            // If the edge is not in the path, add it to the path
            path.addEdge(edge);
        }
    }

    // Return the graph path
    return path;
}

