public int addConstantNameAndType(final String name, final String descriptor) {

    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPool.size(); i++) {
        Symbol symbol = constantPool.get(i);
        if (symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            return i;
        }
    }

    // If not, create a new Symbol with the given value
    Symbol newSymbol = new Symbol(name, descriptor);
    constantPool.add(newSymbol);
    return constantPool.size() - 1;
}

private String unescapeId(String input) {
    // Check if the input is null or empty
    if (input == null || input.isEmpty()) {
        return input;
    }

    // Check if the input starts with a backslash
    if (input.charAt(0) == '\\') {
        // Remove the backslash and return the rest of the input
        return input.substring(1);
    }

    // Check if the input contains any escaped characters
    if (input.contains("\\")) {
        // Replace all escaped characters with their unescaped versions
        return input.replaceAll("\\\\(.)", "$1");
    }

    // Return the input as is
    return input;
}

