public void overrideName(String oldName, String newName) {

    // Check if the old name is not null or empty
    if (oldName == null || oldName.isEmpty()) {
        throw new IllegalArgumentException("Old name cannot be null or empty");
    }

    // Check if the new name is not null or empty
    if (newName == null || newName.isEmpty()) {
        throw new IllegalArgumentException("New name cannot be null or empty");
    }

    // Check if the old name is already used in the storage level
    if (this.storageLevel.containsKey(oldName)) {
        throw new IllegalArgumentException("Old name is already used in the storage level");
    }

    // Check if the new name is already used in the storage level
    if (this.storageLevel.containsKey(newName)) {
        throw new IllegalArgumentException("New name is already used in the storage level");
    }

    // Replace the old name with the new name in the storage level
    this.storageLevel.put(newName, this.storageLevel.get(oldName));
    this.storageLevel.remove(oldName);
}

