public ByteVector putInt(final int intValue) {
  // Check if the byte vector is large enough to hold the int value
  if (this.data.length < this.wpos + 4) {
    // If not, resize the byte vector to double its current size
    byte[] newData = new byte[this.data.length * 2];
    System.arraycopy(this.data, 0, newData, 0, this.data.length);
    this.data = newData;
  }

  // Put the int value into the byte vector
  this.data[this.wpos++] = (byte) (intValue >>> 24);
  this.data[this.wpos++] = (byte) (intValue >>> 16);
  this.data[this.wpos++] = (byte) (intValue >>> 8);
  this.data[this.wpos++] = (byte) intValue;

  return this;
}

