public void abbreviate(final int nameStart, final StringBuffer buf) {

    // Check if the nameStart is valid
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart: " + nameStart);
    }

    // Get the first character of the name
    char firstChar = buf.charAt(nameStart);

    // Check if the first character is a letter
    if (!Character.isLetter(firstChar)) {
        throw new IllegalArgumentException("Invalid name: " + buf.substring(nameStart));
    }

    // Abbreviate the name
    buf.setCharAt(nameStart, Character.toUpperCase(firstChar));
    for (int i = nameStart + 1; i < buf.length(); i++) {
        char c = buf.charAt(i);
        if (Character.isLetter(c)) {
            buf.setCharAt(i, '.');
        }
    }
}

