public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or empty
    if (graph == null || graph.isEmpty()) {
        return false;
    }

    // Check if the vertices set is null or empty
    if (vertices == null || vertices.isEmpty()) {
        return false;
    }

    // Check if the graph contains all the vertices in the set
    if (!graph.containsAll(vertices)) {
        return false;
    }

    // Check if the graph is connected
    if (!isConnected(graph)) {
        return false;
    }

    // Check if the graph is a clique
    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    // Check if the input list is empty
    if (keys.isEmpty()) {
        return Collections.emptyList();
    }

    // Initialize the lower bounds list with the first key
    List<Integer> lowerBounds = new ArrayList<>();
    lowerBounds.add(keys.get(0));

    // Iterate over the remaining keys
    for (int i = 1; i < keys.size(); i++) {
        // Get the current key and its lower bound
        K key = keys.get(i);
        int lowerBound = lowerBounds.get(i - 1);

        // Check if the current key is less than the lower bound
        if (key.compareTo(lowerBound) < 0) {
            // If so, update the lower bound
            lowerBounds.set(i - 1, key);
        }
    }

    return lowerBounds;
}

public void pop(final String descriptor) {

    // Check if the descriptor is a type or method descriptor
    if (descriptor.startsWith("(")) {
        // If it's a method descriptor, pop its argument types
        String[] argumentTypes = descriptor.substring(1, descriptor.length() - 1).split(";");
        for (String argumentType : argumentTypes) {
            pop(argumentType);
        }
    } else {
        // If it's a type descriptor, pop the type
        pop(descriptor);
    }
}

