private List<Integer> computeUpperBounds(List<K> keys) {
    // Check if the input list is empty
    if (keys.isEmpty()) {
        throw new IllegalArgumentException("The input list is empty");
    }

    // Initialize the upper bound list
    List<Integer> upperBounds = new ArrayList<Integer>();

    // Iterate over the keys and compute the upper bound for each key
    for (K key : keys) {
        // Get the current key's index
        int index = keys.indexOf(key);

        // Check if the current key is the last key in the list
        if (index == keys.size() - 1) {
            // If the current key is the last key, the upper bound is the last key's value
            upperBounds.add(keys.get(index).intValue());
        } else {
            // If the current key is not the last key, the upper bound is the next key's value
            upperBounds.add(keys.get(index + 1).intValue());
        }
    }

    return upperBounds;
}

