public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid relative path");
    }

    // Check if the path is valid
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Invalid path");
    }

    // Split the relative path into its components
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is absolute
    if (relativePathComponents[0].isEmpty()) {
        // If the relative path is absolute, return the full path
        return path;
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");

    // Check if the path is absolute
    if (pathComponents[0].isEmpty()) {
        // If the path is absolute, return the full path
        return path;
    }

    // Iterate over the relative path components and update the path components
    for (int i = 0; i < relativePathComponents.length; i++) {
        String relativePathComponent = relativePathComponents[i];

        // Check if the relative path component is a ".."
        if (relativePathComponent.equals("..")) {
            // If the relative path component is "..", remove the last path component
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
        } else {
            // Otherwise, add the relative path component to the path components
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = relativePathComponent;
        }
    }

    // Join the path components into a single string
    String fullPath = String.join("/", pathComponents);

    // Return the full path
    return fullPath;
}

